-- VEGA CRM 2.0 / Phase 1. Run through Supabase SQL editor or migration tooling.
create type public.project_status as enum ('planning', 'live', 'at_risk', 'completed');
create type public.project_role as enum ('admin', 'project_director', 'sales', 'operations', 'viewer');
create type public.booth_status as enum ('available', 'reserved', 'sold', 'blocked');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null, role public.project_role not null default 'viewer', created_at timestamptz not null default now());
create table public.projects (id uuid primary key default gen_random_uuid(), code text unique not null, name text not null, city text, country text, starts_on date, ends_on date, status public.project_status not null default 'planning', default_currency char(3) not null default 'USD', created_by uuid not null references public.profiles(id), created_at timestamptz not null default now());
create table public.project_members (project_id uuid references public.projects(id) on delete cascade, user_id uuid references public.profiles(id) on delete cascade, role public.project_role not null, primary key(project_id,user_id));
create table public.halls (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, name text not null, sort_order int not null default 0, unique(project_id,name));
create table public.booths (id uuid primary key default gen_random_uuid(), hall_id uuid not null references public.halls(id) on delete cascade, code text not null, x numeric not null, y numeric not null, width numeric not null default 1, height numeric not null default 1, status public.booth_status not null default 'available', exhibitor_name text, unique(hall_id,code));
create table public.project_documents (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, title text not null, file_path text not null, uploaded_by uuid not null references public.profiles(id), created_at timestamptz not null default now());
create table public.announcements (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id) on delete cascade, body text not null, published_at timestamptz, author_id uuid not null references public.profiles(id));
alter table public.profiles enable row level security; alter table public.projects enable row level security; alter table public.project_members enable row level security; alter table public.halls enable row level security; alter table public.booths enable row level security; alter table public.project_documents enable row level security; alter table public.announcements enable row level security;
create function public.is_project_member(target_project uuid) returns boolean language sql stable security invoker set search_path = '' as $$ select exists(select 1 from public.project_members pm where pm.project_id = target_project and pm.user_id = (select auth.uid())) or exists(select 1 from public.profiles p where p.id = (select auth.uid()) and p.role = 'admin') $$;
create policy "Users view their own profile" on public.profiles for select to authenticated using ((select auth.uid()) = id);
create policy "Members view projects" on public.projects for select to authenticated using (public.is_project_member(id));
create policy "Admins create projects" on public.projects for insert to authenticated with check (exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='admin'));
create policy "Members view assignments" on public.project_members for select to authenticated using (public.is_project_member(project_id));
create policy "Members view halls" on public.halls for select to authenticated using (public.is_project_member(project_id));
create policy "Members view booths" on public.booths for select to authenticated using (exists(select 1 from public.halls h where h.id=hall_id and public.is_project_member(h.project_id)));
create policy "Operations update booths" on public.booths for update to authenticated using (exists(select 1 from public.halls h join public.project_members pm on pm.project_id=h.project_id where h.id=hall_id and pm.user_id=(select auth.uid()) and pm.role in ('admin','project_director','operations','sales'))) with check (exists(select 1 from public.halls h join public.project_members pm on pm.project_id=h.project_id where h.id=hall_id and pm.user_id=(select auth.uid()) and pm.role in ('admin','project_director','operations','sales')));
create policy "Members view project documents" on public.project_documents for select to authenticated using (public.is_project_member(project_id));
create policy "Members view announcements" on public.announcements for select to authenticated using (public.is_project_member(project_id));
